    _builtin_params = {"mfactor": 1.0}
    _builtin_params.update(builtin_params)
    _given = _pyosdi_effective_given(params, given)
    _params = _pyosdi_merge_given_params(_pyosdi_model_value(model, "inst_defaults"), params, _given)
